function minimumCost(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  const digits = String(median);
  const odd = digits.length % 2 === 1;
  const half = Number(digits.slice(0, Math.ceil(digits.length / 2)));

  const mirror = (head) => {
    const text = String(head);
    const tail = odd ? text.slice(0, -1) : text;
    return Number(text + [...tail].reverse().join(''));
  };

  const candidates = [
    10 ** (digits.length - 1) - 1,
    10 ** digits.length + 1,
    mirror(half - 1),
    mirror(half),
    mirror(half + 1),
  ];
  let below = 0;
  let above = Infinity;
  for (const candidate of candidates) {
    if (candidate > 0 && candidate <= median) {
      below = Math.max(below, candidate);
    }
    if (candidate >= median) {
      above = Math.min(above, candidate);
    }
  }

  const cost = (target) => {
    let total = 0;
    for (const value of nums) {
      total += Math.abs(value - target);
    }
    return total;
  };
  return Math.min(cost(below), cost(above));
}

