function minimumCost(nums) {
  const largest = Math.max(...nums);
  let best = Infinity;
  // Palindromes in increasing order: every length, every first half.
  for (let length = 1; length <= 11; length++) {
    const halfLength = Math.ceil(length / 2);
    for (let h = 10 ** (halfLength - 1); h < 10 ** halfLength; h++) {
      const left = String(h);
      const right = left.slice(0, length - halfLength).split('').reverse().join('');
      const p = Number(left + right);
      let total = 0;
      for (const x of nums) total += Math.abs(x - p);
      best = Math.min(best, total);
      // Beyond the first palindrome >= max, totals only grow.
      if (p >= largest) return best;
    }
  }
  return best;
}

