function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  const mode = int(0, 3);
  const nums = [];
  for (let i = 0; i < n; i++) {
    let value;
    if (mode === 0) value = int(1, size === 'large' ? 1e9 : 200);
    else if (mode === 1) {
      // Cluster around a power of ten, where palindromes change length.
      const k = int(1, 9);
      value = Math.min(1e9, Math.max(1, 10 ** k + int(-3, 3)));
    } else if (mode === 2) value = int(1, 1e9);
    else {
      // Cluster around one random centre.
      value = Math.min(1e9, Math.max(1, 123456789 + int(-50000, 50000) * (size === 'large' ? 7 : 1)));
    }
    nums.push(value);
  }
  return [nums];
}
